/*
 * MEIKO — languages.
 * English is the source language of the code. A translation is a list in js/lang/<code>.js that lines up,
 * entry by entry, with the English list in js/lang/strings.js (both are generated by tools/i18n-build.js).
 * Instead of changing every module, the page is translated where it is shown: a MutationObserver swaps
 * each English text node and the placeholder / title / aria-label attributes for the chosen language.
 * The original English is remembered per node, so switching language (or back to English) needs no reload.
 * Mark user content (chat, names) with translate="no" so it is never touched.
 */
(function () {
  'use strict';
  window.MEIKO = window.MEIKO || {};
  var LANGS = [
    { code: 'id', name: 'Bahasa Indonesia', en: 'Indonesian', locale: 'id-ID' },
    { code: 'en', name: 'English', en: 'English', locale: 'en-GB' },
    { code: 'ms', name: 'Bahasa Melayu', en: 'Malay', locale: 'ms-MY' },
    { code: 'tl', name: 'Filipino', en: 'Filipino', locale: 'fil-PH' },
    { code: 'vi', name: 'Tiếng Việt', en: 'Vietnamese', locale: 'vi-VN' },
    { code: 'th', name: 'ไทย', en: 'Thai', locale: 'th-TH' },
    { code: 'zh', name: '简体中文', en: 'Chinese (Simplified)', locale: 'zh-CN' }
  ];
  var KEYS = { // short keys still used by MEIKO.t (English; the page translator does the rest)
    'cat.navigation': 'Navigation', 'cat.calculator': 'Calculator', 'cat.converter': 'Unit Converter',
    'cat.astronomy': 'Astronomy', 'cat.prayer': 'Prayer Tools', 'cat.position': 'Position & GPS', 'cat.settings': 'Settings',
    'nav.home': 'Home', 'nav.navigate': 'Navigate', 'nav.qibla': 'Qibla', 'nav.gps': 'GPS', 'nav.settings': 'Settings',
    'tagline': 'Navigate • Calculate • Explore'
  };
  var lang = 'en', lists = {}, map = null, memo = null, byFirst = null, loading = {}, ready = [];
  var PASS = /^(?:[NSEWTMh]|NM|nm|km|kn|kt|m|ft|mi|mph|kmh|cbl|fm|UTC|GMT|GPS|MEIKO|COG|SOG|ETA|ETD|DTW|BRG|XTE|VMG|HDOP|NMEA|USB|BLE|GPX|Hz|KB|MB|AM|PM|DD|DDM|DMS|WIB|WITA|WIT)$/;
  var ATTRS = ['placeholder', 'title', 'aria-label', 'label'];
  var SKIP = 'script,style,textarea,svg,[translate="no"],[contenteditable="true"]';
  var srcText = new WeakMap(), srcAttr = new WeakMap(), observer = null, busy = false;

  function info(code) { return LANGS.filter(function (l) { return l.code === code; })[0]; }
  /** Best guess from the browser language (used until the person picks one). */
  function detect() {
    var list = (navigator.languages && navigator.languages.length ? navigator.languages : [navigator.language || 'en']);
    for (var i = 0; i < list.length; i++) {
      var c = String(list[i] || '').toLowerCase().split('-')[0];
      if (c === 'in') c = 'id'; if (c === 'fil') c = 'tl';
      if (info(c)) return c;
    }
    return 'en';
  }
  function norm(s) { return s.replace(/\s+/g, ' ').trim(); }

  function build() {
    map = null; memo = new Map(); byFirst = null;
    var src = MEIKO.i18n.SRC, tr = lists[lang];
    if (lang === 'en' || !src || !tr) return;
    map = new Map(); byFirst = new Map();
    for (var i = 0; i < src.length; i++) {
      if (!tr[i]) continue;
      map.set(src[i], tr[i]);
      var w = firstWord(src[i]); if (!w) continue;
      var a = byFirst.get(w); if (!a) byFirst.set(w, a = []); a.push(src[i]);
    }
    byFirst.forEach(function (a) { a.sort(function (x, y) { return y.length - x.length; }); });
  }
  function firstWord(s) { var m = /^[^A-Za-z]*([A-Za-z]+)/.exec(s); return m ? m[1].toLowerCase() : ''; }

  /**
   * Translate one piece of text. Tries, in order: the whole text; the text without the leading/trailing
   * numbers and signs ("3 vessels online"); then cover it with known phrases from left to right. If any
   * English word is left over the text stays English, so a half-translated sentence is never shown.
   */
  function tr(s) {
    if (!map || !s) return s;
    var k = norm(s); if (!k || !/[A-Za-z]/.test(k)) return s;
    var res = memo.has(k) ? memo.get(k) : look(k);
    if (res == null) return s;
    return /^\s*/.exec(s)[0].replace(/\s+/, ' ') + res + /\s*$/.exec(s)[0].replace(/\s+/, ' ');
  }
  function look(k) {
    var out = map.get(k);
    if (out == null) {
      var m = /^([^A-Za-z“"(]*)(.*?)([^A-Za-z”")]*)$/.exec(k);
      if (m && m[2] && m[2] !== k && map.has(m[2])) out = m[1] + map.get(m[2]) + m[3];
    }
    if (out == null) out = cover(k);
    if (memo.size > 5000) memo.clear();
    memo.set(k, out);
    return out;
  }
  function cover(k) {
    var i = 0, out = '', n = k.length, hits = 0;
    while (i < n) {
      var ch = k[i];
      if (ch === '“' || ch === '"') { // quoted user text (a name, a file) is kept as it is
        var j = k.indexOf(ch === '“' ? '”' : '"', i + 1); if (j < 0) return null;
        out += k.slice(i, j + 1); i = j + 1; continue;
      }
      if (!/[A-Za-z]/.test(ch)) { out += ch; i++; continue; }
      var word = /^[A-Za-z]+/.exec(k.slice(i))[0];
      if (PASS.test(word) && !/[A-Za-z]/.test(k[i - 1] || '')) { out += word; i += word.length; continue; } // units, N/S/E/W, names
      var w = word.toLowerCase(), cands = byFirst.get(w), hit = null;
      if (cands) for (var c = 0; c < cands.length; c++) {
        var cand = cands[c], lead = /^[^A-Za-z]*/.exec(cand)[0].length, start = i - lead;
        if (start < 0 || k.substr(start, cand.length) !== cand) continue;
        var after = k[start + cand.length];
        if (after && /[A-Za-z0-9]/.test(after) && /[A-Za-z0-9]$/.test(cand)) continue; // whole words only
        hit = cand; out = out.slice(0, out.length - lead) + map.get(cand); i = start + cand.length; break;
      }
      if (!hit) return null;
      hits++;
    }
    return hits ? out : null;
  }

  function skipped(el) { return !el || (el.closest && el.closest(SKIP)); }
  function doText(node) {
    var rec = srcText.get(node), cur = node.nodeValue;
    if (rec && cur === rec.out) return; // our own value
    var src = cur; // new English text from the app
    if (!/[A-Za-z]/.test(src)) { if (rec) srcText.delete(node); return; }
    if (skipped(node.parentElement)) return;
    var t = tr(src);
    if (t !== src) { srcText.set(node, { src: src, out: t }); busy = true; node.nodeValue = t; busy = false; }
    else if (rec) srcText.delete(node);
  }
  function doAttrs(el) {
    if (el.nodeType !== 1 || skipped(el)) return;
    var rec = srcAttr.get(el);
    for (var i = 0; i < ATTRS.length; i++) {
      var a = ATTRS[i]; if (!el.hasAttribute(a)) continue;
      var cur = el.getAttribute(a), r = rec && rec[a];
      if (r && cur === r.out) continue;
      var t = tr(cur);
      if (t !== cur) { if (!rec) srcAttr.set(el, rec = {}); rec[a] = { src: cur, out: t }; el.setAttribute(a, t); }
      else if (r) delete rec[a];
    }
  }
  function walk(root) {
    if (!root) return;
    if (root.nodeType === 3) return doText(root);
    if (root.nodeType !== 1 && root.nodeType !== 11) return;
    if (root.nodeType === 1 && skipped(root)) return;
    if (root.nodeType === 1) doAttrs(root);
    var w = document.createTreeWalker(root, NodeFilter.SHOW_ELEMENT | NodeFilter.SHOW_TEXT, {
      acceptNode: function (n) { return n.nodeType === 1 && n.matches(SKIP) ? NodeFilter.FILTER_REJECT : NodeFilter.FILTER_ACCEPT; }
    });
    var n; while ((n = w.nextNode())) { if (n.nodeType === 3) doText(n); else doAttrs(n); }
  }
  /** Put every translated node back to its English source (before switching language). */
  function restore(root) {
    var w = document.createTreeWalker(root, NodeFilter.SHOW_ELEMENT | NodeFilter.SHOW_TEXT), n;
    while ((n = w.nextNode())) {
      if (n.nodeType === 3) { var r = srcText.get(n); if (r && n.nodeValue === r.out) n.nodeValue = r.src; srcText.delete(n); }
      else { var ra = srcAttr.get(n); if (ra) { Object.keys(ra).forEach(function (a) { if (n.getAttribute(a) === ra[a].out) n.setAttribute(a, ra[a].src); }); srcAttr.delete(n); } }
    }
  }
  function observe() {
    if (observer || !window.MutationObserver || !document.body) return;
    observer = new MutationObserver(function (list) {
      if (busy || !map) return;
      for (var i = 0; i < list.length; i++) {
        var m = list[i];
        if (m.type === 'childList') for (var j = 0; j < m.addedNodes.length; j++) walk(m.addedNodes[j]);
        else if (m.type === 'characterData') doText(m.target);
        else if (m.type === 'attributes') doAttrs(m.target);
      }
    });
    observer.observe(document.body, { childList: true, subtree: true, characterData: true, attributes: true, attributeFilter: ATTRS });
  }
  function applyAll() {
    var root = document.documentElement, l = info(lang);
    root.setAttribute('lang', lang === 'tl' ? 'fil' : lang);
    if (!document.body) return;
    restore(document.body);
    build();
    if (map) walk(document.body);
    observe();
    document.title = tr(document.title);
    root.classList.remove('i18n-wait');
  }
  function load(code, cb) {
    if (code === 'en' || lists[code]) return cb();
    var files = [];
    if (!MEIKO.i18n.SRC) files.push('js/lang/strings.js');
    files.push('js/lang/' + code + '.js');
    var left = files.length, done = function () { if (--left === 0) cb(); };
    files.forEach(function (f) {
      if (loading[f]) { loading[f].push(done); return; }
      loading[f] = [done];
      var s = document.createElement('script'); s.src = f; s.async = false;
      s.onload = s.onerror = function () { var q = loading[f]; loading[f] = null; q.forEach(function (fn) { fn(); }); };
      document.head.appendChild(s);
    });
  }
  function setLang(code) {
    if (!info(code)) code = 'en';
    lang = code;
    if (code !== 'en' && !lists[code] && document.body) document.documentElement.classList.add('i18n-wait');
    load(code, function () {
      if (lang !== code) return;
      if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', applyAll); else applyAll();
      ready.splice(0).forEach(function (fn) { try { fn(); } catch (e) {} });
    });
    setTimeout(function () { document.documentElement.classList.remove('i18n-wait'); }, 1500); // never hide the app for long
  }

  // Native dialogs show translated text too.
  ['alert', 'confirm', 'prompt'].forEach(function (fn) {
    var orig = window[fn]; if (typeof orig !== 'function') return;
    window[fn] = function (msg) { var a = Array.prototype.slice.call(arguments); a[0] = tr(String(msg == null ? '' : msg)); return orig.apply(window, a); };
  });

  MEIKO.i18n = {
    LANGS: LANGS,
    setLang: setLang,
    lang: function () { return lang; },
    locale: function () { var l = info(lang); return l ? l.locale : 'en-GB'; },
    languages: function () { return LANGS.map(function (l) { return l.code; }); },
    info: info,
    detect: detect,
    /** Translate an English UI string into the current language (falls back to English). */
    tr: function (s) { return tr(s); },
    /** Called by js/lang/<code>.js. */
    add: function (code, list) { lists[code] = list; },
    /** Run fn once the current language's list is loaded. */
    onReady: function (fn) { if (lang === 'en' || lists[lang]) fn(); else ready.push(fn); },
    /** Translate a subtree now (e.g. a detached element about to be shown). */
    translate: function (root) { if (map) walk(root); }
  };
  // English on purpose: the page translator swaps it when shown, and can swap it again on a language change.
  MEIKO.t = function (key, fallback) { return KEYS[key] || fallback || key; };
})();
